import org.apache.commons.lang3.builder.ToStringBuilder;
import org.apache.commons.lang3.builder.MultilineRecursiveToStringStyle;
import org.apache.commons.lang3.builder.ReflectionToStringBuilder;

public class Probe {
    static class Job {
        String title;
    }
    static class Person {
        String name;
        int age;
        boolean smoker;
        Job job;
        int[] nums;
        Object[] objs;
    }
    public static void main(String[] args) throws Exception {
        Integer base = Integer.valueOf(5);
        MultilineRecursiveToStringStyle style = new MultilineRecursiveToStringStyle();
        String blank = new ToStringBuilder(base, style).toString();
        print("BLANK", blank);

        String withInt = new ToStringBuilder(base, style).append("a", 3).toString();
        print("INT", withInt);

        String withTwo = new ToStringBuilder(base, style).append("a", 3).append("b", 4).toString();
        print("TWO", withTwo);

        int[] arr = {1, 2, 3};
        String withArr = new ToStringBuilder(base, style).append("arr", arr).toString();
        print("ARR", withArr);

        Object[] oarr = {null, "x"};
        String withOArr = new ToStringBuilder(base, style).append("oarr", oarr).toString();
        print("OARR", withOArr);

        Person p = new Person();
        p.name = "John";
        p.age = 33;
        p.smoker = false;
        p.job = new Job();
        p.job.title = "Manager";
        p.nums = new int[] {7, 8};
        p.objs = new Object[] {"y"};
        ReflectionToStringBuilder b = new ReflectionToStringBuilder(p, style);
        String personStr = b.toString();
        System.out.println("PERSON_FORCE=" + b.isForceAccessible());
        print("PERSON", personStr);

        String withObj = new ToStringBuilder(base, style).append("o", (Object) p).toString();
        print("WITHOBJ", withObj);

        String withNull = new ToStringBuilder(base, style).append("n", (Object) null).toString();
        print("NULL", withNull);

        String withStr = new ToStringBuilder(base, style).append("s", "hello").toString();
        print("STR", withStr);

        String withWrapper = new ToStringBuilder(base, style).append("w", Integer.valueOf(9)).toString();
        print("WRAPPER", withWrapper);

        String seq1 = new ToStringBuilder(base, style).append("arr", arr).toString();
        String seq2 = new ToStringBuilder(base, style).append("a", 3).toString();
        print("SEQ1", seq1);
        print("SEQ2", seq2);

        String emptyArr = new ToStringBuilder(base, style).append("arr", new int[0]).toString();
        print("EMPTYARR", emptyArr);
    }

    static void print(String label, String s) {
        StringBuilder out = new StringBuilder();
        out.append(label).append("=[");
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '\n') {
                out.append("\\n");
            } else if (c == '\r') {
                out.append("\\r");
            } else {
                out.append(c);
            }
        }
        out.append("]");
        System.out.println(out.toString());
    }
}
